    /// Toggles whether non-administrators can receive only administrators and bots using getSupergroupMembers or searchChatMembers. Can be called only if supergroupFullInfo.can_hide_members == true
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ToggleSupergroupHasHiddenMembersAsync(long supergroupId = default, bool hasHiddenMembers = default)
    {

           using var activity =  StartCallActivity("ToggleSupergroupHasHiddenMembersAsync", typeof(ToggleSupergroupHasHiddenMembers).FullName ?? "ToggleSupergroupHasHiddenMembersAsync");

           try
           {
             return client.ToggleSupergroupHasHiddenMembersAsync(supergroupId, hasHiddenMembers);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
